package com.receiptledger.v1;

import android.app.*;import android.graphics.Bitmap;import android.os.Bundle;import android.view.*;import android.widget.*;import com.receiptledger.v1.archive.ReceiptRepository;import com.receiptledger.v1.persistence.*;import com.receiptledger.v1.product.*;import com.receiptledger.v1.ui.ReceiptDisplayFormatter;import com.receiptledger.v1.ui.SystemBarInsetHelper;import java.util.*;import java.util.concurrent.*;

public final class ReceiptDetailActivity extends Activity {
 public static final String EXTRA_ID="receipt_id";private final ExecutorService worker=Executors.newSingleThreadExecutor();private ReceiptRepository repository;private SqliteProductCatalogStore catalog;private LinearLayout content;private Bitmap image;private long generation;
 @Override protected void onCreate(Bundle b){super.onCreate(b);repository=new ReceiptRepository(getApplicationContext());catalog=new SqliteProductCatalogStore(getApplicationContext());int p=dp(12);ScrollView scroll=new ScrollView(this);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(p,p,p,p);scroll.addView(content);setContentView(scroll);SystemBarInsetHelper.apply(this,content);load();}
 private void load(){String id=getIntent().getStringExtra(EXTRA_ID);if(id==null){finish();return;}long ticket=++generation;content.removeAllViews();TextView loading=new TextView(this);loading.setText(R.string.detail_loading);content.addView(loading);worker.execute(()->{ReceiptRecord r=repository.get(id);Bitmap b=repository.loadImage(id,1600);List<IdentityResolution> identities=new ArrayList<>();if(r!=null)for(PersistedItem item:r.items){IdentityResolution existing=catalog.itemResolution(id,item.ordinal);identities.add(existing.classified()?existing:catalog.resolveAndLinkExact(id,item.ordinal,item.name));}runOnUiThread(()->{if(ticket!=generation){if(b!=null)b.recycle();return;}if(r==null){content.removeAllViews();TextView missing=new TextView(this);missing.setText(R.string.detail_missing);content.addView(missing);return;}render(r,b,identities);});});}
 private void render(ReceiptRecord r,Bitmap b,List<IdentityResolution> identities){content.removeAllViews();if(image!=null&&!image.isRecycled())image.recycle();image=b;TextView title=new TextView(this);title.setText(R.string.detail_title);title.setTextSize(22);content.addView(title);if(b!=null){ImageView iv=new ImageView(this);iv.setAdjustViewBounds(true);iv.setScaleType(ImageView.ScaleType.FIT_CENTER);iv.setImageBitmap(b);content.addView(iv,new LinearLayout.LayoutParams(-1,-2));}TextView detail=new TextView(this);detail.setTextIsSelectable(true);detail.setText(ReceiptDisplayFormatter.detail(r));content.addView(detail);TextView identityTitle=new TextView(this);identityTitle.setText(R.string.identity_section);identityTitle.setTextSize(19);content.addView(identityTitle);for(int i=0;i<r.items.size();i++){PersistedItem item=r.items.get(i);IdentityResolution res=identities.get(i);Button row=new Button(this);row.setAllCaps(false);row.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);row.setText(identityText(item,res));final int ordinal=item.ordinal;row.setOnClickListener(v->ProductIdentityDialog.show(this,item.name,res,new ProductIdentityDialog.Callback(){public void onConfirm(ProductType type,String canonical){worker.execute(()->{try{catalog.confirm(r.id,ordinal,item.name,type,canonical,System.currentTimeMillis());runOnUiThread(ReceiptDetailActivity.this::load);}catch(Exception e){runOnUiThread(()->Toast.makeText(ReceiptDetailActivity.this,e.getMessage(),Toast.LENGTH_LONG).show());}});}public void onUnclassify(){worker.execute(()->{catalog.unlinkItem(r.id,ordinal);runOnUiThread(ReceiptDetailActivity.this::load);});}}));content.addView(row);}Button delete=new Button(this);delete.setText(R.string.delete_receipt);delete.setOnClickListener(v->new AlertDialog.Builder(this).setMessage(R.string.delete_confirm).setNegativeButton(android.R.string.cancel,null).setPositiveButton(R.string.delete_receipt,(d,w)->delete(r.id)).show());content.addView(delete);}
 private String identityText(PersistedItem item,IdentityResolution r){return r.classified()?"["+r.product.type+"] "+item.name+" → "+r.product.canonicalName+" ("+r.source+")":"[UNCLASSIFIED] "+item.name;}
 private void delete(String id){worker.execute(()->{catalog.unlinkReceipt(id);repository.delete(id);runOnUiThread(this::finish);});}
 @Override protected void onDestroy(){generation++;worker.shutdownNow();if(image!=null&&!image.isRecycled())image.recycle();catalog.close();repository.close();super.onDestroy();}private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}
}
